package com.phoenix.business;
import com.fasterxml.jackson.databind.*;import com.phoenix.business.domain.User;import com.phoenix.business.repository.UserRepository;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.junit.jupiter.api.Assertions.assertTrue;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ApiSecurityIntegrationTest {
 @Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired PasswordEncoder encoder;@Autowired ObjectMapper json;
 @BeforeEach void accounts(){create("admin","Admin User",User.Role.ADMIN,true);create("staff","Staff User",User.Role.STAFF,true);create("disabled","Disabled User",User.Role.STAFF,false);}
 void create(String username,String display,User.Role role,boolean active){if(users.findByUsernameIgnoreCase(username).isPresent())return;User u=new User();u.setUsername(username);u.setDisplayName(display);u.setRole(role);u.setActive(active);u.setForcePasswordChange(false);u.setPasswordHash(encoder.encode("StrongPass1"));users.save(u);}
 String login(String username,String password)throws Exception{String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(java.util.Map.of("username",username,"password",password)))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("accessToken").asText();}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder auth(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,String role)throws Exception{return r.header("Authorization","Bearer "+login(role,"owner".equals(role)?"StrongOwner1Password":"StrongPass1"));}
 @Test @Order(1) void healthIsPublic()throws Exception{mvc.perform(get("/actuator/health")).andExpect(status().isOk());}
 @Test @Order(2) void dashboardRequiresAuthentication()throws Exception{mvc.perform(get("/api/dashboard")).andExpect(status().isUnauthorized());}
 @Test @Order(3) void successfulLoginReturnsToken()throws Exception{mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"owner\",\"password\":\"StrongOwner1Password\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.accessToken").isNotEmpty()).andExpect(jsonPath("$.user.role").value("OWNER"));}
 @Test @Order(4) void failedAndDisabledLoginAreUnauthorized()throws Exception{mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"owner\",\"password\":\"wrong\"}")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"disabled\",\"password\":\"StrongPass1\"}")).andExpect(status().isUnauthorized());}
 @Test @Order(5) void invalidTokenIsUnauthorized()throws Exception{mvc.perform(get("/api/dashboard").header("Authorization","Bearer invalid.token.value")).andExpect(status().isUnauthorized());}
 @Test @Order(6) void ownerCanListUsersAndStaffCannot()throws Exception{mvc.perform(auth(get("/api/users"),"owner")).andExpect(status().isOk());mvc.perform(auth(get("/api/users"),"staff")).andExpect(status().isForbidden());}
 @Test @Order(7) void staffCannotWritePlansSettingsReportsOrAudit()throws Exception{String t=login("staff","StrongPass1");mvc.perform(post("/api/plans").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Blocked\",\"durationMonths\":1,\"price\":10}")).andExpect(status().isForbidden());mvc.perform(put("/api/settings").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/reports/members.xlsx").header("Authorization","Bearer "+t)).andExpect(status().isForbidden());mvc.perform(get("/api/audit-logs").header("Authorization","Bearer "+t)).andExpect(status().isForbidden());}
 @Test @Order(8) void adminCanCreatePlanAndExportAllReports()throws Exception{String t=login("admin","StrongPass1");mvc.perform(post("/api/plans").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Test Plan\",\"durationMonths\":2,\"price\":1500}")).andExpect(status().isOk());for(String report:new String[]{"members","payments","attendance","expiring","revenue"}){byte[] bytes=mvc.perform(get("/api/reports/"+report+".xlsx").header("Authorization","Bearer "+t)).andExpect(status().isOk()).andExpect(header().string("Content-Type","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).andReturn().getResponse().getContentAsByteArray();assertTrue(bytes.length>100);}}
 @Test @Order(9) void memberValidationAndDuplicatesAreEnforced()throws Exception{String t=login("staff","StrongPass1"),body="{\"memberCode\":\"T001\",\"name\":\"Test Member\",\"phone\":\"9990001111\",\"email\":\"test@example.com\",\"joinDate\":\"2026-09-02\",\"status\":\"ACTIVE\"}";mvc.perform(post("/api/members").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk());mvc.perform(post("/api/members").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content(body.replace("T001","T002"))).andExpect(status().isUnprocessableEntity());mvc.perform(post("/api/members").header("Authorization","Bearer "+t).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Missing required fields\"}")).andExpect(status().isUnprocessableEntity());}
 @Test @Order(10) void logoutRevokesToken()throws Exception{String t=login("staff","StrongPass1");mvc.perform(post("/api/auth/logout").header("Authorization","Bearer "+t)).andExpect(status().isOk());mvc.perform(get("/api/dashboard").header("Authorization","Bearer "+t)).andExpect(status().isUnauthorized());}
 @Test @Order(11) void unknownIdsReturnNotFound()throws Exception{mvc.perform(auth(get("/api/members/999999"),"staff")).andExpect(status().isNotFound());mvc.perform(auth(get("/api/payments/999999/receipt.pdf"),"staff")).andExpect(status().isNotFound());}
 @Test @Order(12) void loginRateLimitReturns429()throws Exception{for(int i=0;i<5;i++)mvc.perform(post("/api/auth/login").with(r->{r.setRemoteAddr("10.1.2.3");return r;}).contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"ghost\",\"password\":\"BadPass1X\"}")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").with(r->{r.setRemoteAddr("10.1.2.3");return r;}).contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"ghost\",\"password\":\"BadPass1X\"}")).andExpect(status().isTooManyRequests());}
}
